$('plot').onfocus=keyboardPoint;$('plot').onblur=()=>$('plotTooltip').hidden=true;
$('plot').onkeydown=e=>{if(!analysis)return;if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();plotCursor=e.key==='Home'?0:e.key==='End'?analysis.freqs.length-1:D.clamp(plotCursor+(e.key==='ArrowRight'?1:-1),0,analysis.freqs.length-1);keyboardPoint();};

